function httpsRequest(options, body) {
  return new Promise((resolve, reject) => {
    const request = https.request({ family: 4, ...options }, response => {
      const chunks = [];
      response.on('data', chunk => chunks.push(chunk));
      response.on('end', () => resolve({ status: response.statusCode, headers: response.headers, body: Buffer.concat(chunks) }));
    });
    request.on('error', reject);
    request.setTimeout(30000, () => request.destroy(new Error('Request to Google timed out.')));
    if (body) request.write(body);
    request.end();
  });
}

function credentials() {
  try {
    if (process.env.GOOGLE_SERVICE_ACCOUNT_JSON) {
      const parsed = JSON.parse(process.env.GOOGLE_SERVICE_ACCOUNT_JSON);
      return { email: parsed.client_email, key: parsed.private_key };
    }
  } catch (_) {}
  return {
    email: process.env.GOOGLE_CLIENT_EMAIL,
    key: process.env.GOOGLE_PRIVATE_KEY && process.env.GOOGLE_PRIVATE_KEY.replace(/\\n/g, '\n')
  };
}

let tokenCache = { value: '', expires: 0 };
function b64url(value) {
  return Buffer.from(value).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

async function accessToken() {
  if (tokenCache.value && Date.now() < tokenCache.expires - 60000) return tokenCache.value;
  const creds = credentials();
  if (!creds.email || !creds.key) return '';
  const now = Math.floor(Date.now() / 1000);
  const unsigned = `${b64url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }))}.${b64url(JSON.stringify({
    iss: creds.email,
    scope: 'https://www.googleapis.com/auth/spreadsheets',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now,
    exp: now + 3600
  }))}`;
  const signature = crypto.sign('RSA-SHA256', Buffer.from(unsigned), creds.key);
  const assertion = `${unsigned}.${b64url(signature)}`;
  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer', assertion })
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error_description || 'Google authentication failed.');
  tokenCache = { value: data.access_token, expires: Date.now() + (data.expires_in || 3600) * 1000 };
  return tokenCache.value;
}

async function google(path, options = {}) {
  const token = await accessToken();
  if (!token) throw Object.assign(new Error('Google Sheets write access is not configured.'), { status: 503, setup: true });
  const response = await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${SPREADSHEET_ID}${path}`, {
    ...options,
    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json', ...(options.headers || {}) }
  });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error?.message || 'Google Sheets request failed.');
  return body;
}

function oauthTokenRequest(params) {
  if (!OAUTH_CLIENT_ID || !OAUTH_CLIENT_SECRET) throw new Error('Google Drive OAuth is not configured.');
  const body = new URLSearchParams(params).toString();
  return httpsRequest({
    method: 'POST', hostname: 'oauth2.googleapis.com', path: '/token',
    headers: { 'content-type': 'application/x-www-form-urlencoded', 'content-length': Buffer.byteLength(body) }
  }, body).then(response => {
    const data = JSON.parse(response.body.toString() || '{}');
    if (response.status >= 400) throw new Error(data.error_description || data.error || 'Google OAuth request failed.');
    return data;
  });
}

let driveTokenCache = { value: '', expires: 0 };
async function driveAccessToken() {
  if (!OAUTH_REFRESH_TOKEN) throw new Error('Google Drive is not connected yet. Open /oauth/setup after deployment.');
  if (driveTokenCache.value && Date.now() < driveTokenCache.expires - 60000) return driveTokenCache.value;
  const data = await oauthTokenRequest({
    client_id: OAUTH_CLIENT_ID, client_secret: OAUTH_CLIENT_SECRET,
    refresh_token: OAUTH_REFRESH_TOKEN, grant_type: 'refresh_token'
  });
  driveTokenCache = { value: data.access_token, expires: Date.now() + (data.expires_in || 3600) * 1000 };
  return driveTokenCache.value;
}

function computeRedirectUri(req) {
  if (process.env.OAUTH_REDIRECT_URI) return process.env.OAUTH_REDIRECT_URI;
  const proto = String(req.headers['x-forwarded-proto'] || req.protocol || 'https').split(',')[0].trim();
  const host = req.headers['x-forwarded-host'] || req.headers.host;
  return `${proto}://${host}/oauth/callback`;
}

function buildAuthUrl(redirectUri) {
  if (!OAUTH_CLIENT_ID) throw new Error('GOOGLE_OAUTH_CLIENT_ID is missing.');
  return 'https://accounts.google.com/o/oauth2/v2/auth?' + new URLSearchParams({
    client_id: OAUTH_CLIENT_ID, redirect_uri: redirectUri, response_type: 'code',
    access_type: 'offline', prompt: 'consent', scope: DRIVE_SCOPE
  }).toString();
}

async function driveUpload(buffer, mime, name) {
  const token = await driveAccessToken();
  const boundary = '----x17' + crypto.randomBytes(8).toString('hex');
  const metadata = { name };
  if (DRIVE_FOLDER_ID) metadata.parents = [DRIVE_FOLDER_ID];
  const before = Buffer.from(`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n--${boundary}\r\nContent-Type: ${mime}\r\n\r\n`);
  const payload = Buffer.concat([before, buffer, Buffer.from(`\r\n--${boundary}--`)]);
  const response = await httpsRequest({
    method: 'POST', hostname: 'www.googleapis.com', path: '/upload/drive/v3/files?uploadType=multipart&fields=id',
    headers: { authorization: `Bearer ${token}`, 'content-type': `multipart/related; boundary=${boundary}`, 'content-length': payload.length }
  }, payload);
  const data = JSON.parse(response.body.toString() || '{}');
  if (response.status >= 400) throw new Error(data.error?.message || 'Google Drive upload failed.');
  return data.id;
}

async function driveFile(fileId, media) {
  const token = await driveAccessToken();
  const response = await httpsRequest({
    method: 'GET', hostname: 'www.googleapis.com',
    path: `/drive/v3/files/${encodeURIComponent(fileId)}?${media ? 'alt=media' : 'fields=name,mimeType'}`,
    headers: { authorization: `Bearer ${token}` }
  });
  if (response.status >= 400) {
    let message = 'Google Drive file request failed.';
    try { message = JSON.parse(response.body.toString()).error.message; } catch (_) {}
    throw new Error(message);
  }
  return media ? response.body : JSON.parse(response.body.toString() || '{}');
}

function photoUrl(value) {
  const text = String(value || '').trim();
  if (!text || text.startsWith('data:image/') || text.startsWith('/api/photo/')) return text;
  let match = text.match(/drive\.google\.com\/file\/d\/([^/]+)/);
  if (!match && text.includes('drive.google.com')) match = text.match(/[?&]id=([^&]+)/);
  return match ? `/api/photo/${match[1]}` : text;
}

function safePage(title, body) {
  const clean = value => String(value || '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${clean(title)}</title><style>body{background:#fff;color:#0f172a;font:16px system-ui;max-width:700px;margin:50px auto;padding:20px}h1{color:#0b2545;font-weight:700}textarea{width:100%;height:110px;padding:10px;border:1px solid #e2e8f0;border-radius:8px}a{color:#3b82f6}</style></head><body><h1>${clean(title)}</h1>${body}</body></html>`;
}

function parseCsv(text) {
  const rows = [];
  let row = [], cell = '', quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"' && text[i + 1] === '"') { cell += '"'; i++; }
      else if (ch === '"') quoted = false;
      else cell += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { row.push(cell); cell = ''; }
    else if (ch === '\n') { row.push(cell.replace(/\r$/, '')); rows.push(row); row = []; cell = ''; }
    else cell += ch;
  }
  if (cell || row.length) { row.push(cell.replace(/\r$/, '')); rows.push(row); }
  return rows;
}

async function publicSheet(sheet) {
  const url = `https://docs.google.com/spreadsheets/d/${SPREADSHEET_ID}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(sheet)}&_=${Date.now()}`;
  const response = await fetch(url, { headers: { 'user-agent': 'X17-Technologies-CRM/1.0' } });
  if (!response.ok) throw new Error(`Unable to read ${sheet}.`);
  return parseCsv(await response.text());
}

