app.get('/logo.png', (_req, res) => {
  res.set({ 'content-type': 'image/png', 'cache-control': 'public, max-age=31536000, immutable' });
  res.send(Buffer.from(LOGO_BASE64, 'base64'));
});

app.post('/api/upload', async (req, res) => {
  try {
    const dataUrl = String(req.body?.dataUrl || '');
    const match = dataUrl.match(/^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$/);
    if (!match) return res.status(400).json({ error: 'Invalid picture data.' });
    const mime = `image/${match[1]}`;
    const buffer = Buffer.from(match[2], 'base64');
    if (!buffer.length || buffer.length > 8 * 1024 * 1024) return res.status(400).json({ error: 'Picture must be smaller than 8 MB after processing.' });
    const extension = match[1] === 'jpeg' ? 'jpg' : match[1];
    const fileId = await driveUpload(buffer, mime, `x17-customer-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.${extension}`);
    res.status(201).json({ url: `/api/photo/${fileId}`, fileId });
  } catch (error) { res.status(500).json({ error: error.message }); }
});

app.get('/api/photo/:fileId', async (req, res) => {
  try {
    if (!/^[A-Za-z0-9_-]+$/.test(req.params.fileId)) return res.status(400).json({ error: 'Invalid picture ID.' });
    const metadata = await driveFile(req.params.fileId, false);
    const media = await driveFile(req.params.fileId, true);
    res.set({ 'content-type': metadata.mimeType || 'application/octet-stream', 'cache-control': 'private, max-age=86400' });
    if (req.query.download) res.set('content-disposition', `attachment; filename="${String(metadata.name || 'picture').replace(/["\r\n]/g, '')}"`);
    res.send(media);
  } catch (error) { res.status(502).json({ error: error.message }); }
});

app.get('/oauth/setup', (req, res) => {
  try { res.redirect(buildAuthUrl(computeRedirectUri(req))); }
  catch (error) { res.status(500).type('html').send(safePage('Google Drive setup', `<p>${String(error.message).replace(/[&<>]/g, '')}</p>`)); }
});

app.get('/oauth/callback', async (req, res) => {
  try {
    if (!req.query.code) {
      const reason = String(req.query.error_description || req.query.error || 'Google did not return an authorization code.').replace(/[&<>]/g, '');
      return res.status(400).type('html').send(safePage('Google Drive was not connected', `<p>${reason}</p><p><a href="/oauth/setup">Try connecting again</a></p>`));
    }
    const tokens = await oauthTokenRequest({
      code: String(req.query.code), client_id: OAUTH_CLIENT_ID, client_secret: OAUTH_CLIENT_SECRET,
      redirect_uri: computeRedirectUri(req), grant_type: 'authorization_code'
    });
    if (!tokens.refresh_token) throw new Error('Google did not return a refresh token. Remove the app from your Google Account permissions and try again.');
    res.type('html').send(safePage('Google Drive connected', `<p>Copy this value into Railway as <strong>GOOGLE_OAUTH_REFRESH_TOKEN</strong>, then redeploy:</p><textarea readonly>${tokens.refresh_token}</textarea><p>Keep this token private.</p>`));
  } catch (error) { res.status(500).type('html').send(safePage('Google Drive connection error', `<p>${String(error.message).replace(/[&<>]/g, '')}</p>`)); }
});

