  async function saveCostEntry(e){e.preventDefault();var orderNumber=$('costOrderNumber').value;if(!orderNumber){toast('Pick an order first.',true);return}var items=[];rawMaterials.forEach(function(m,i){items.push({description:m.description,qty:Number(m.qty)||0,amount:Number(costLineAmounts[i])||0,supplier:String(costLineSuppliers[i]||'')})});selectedRouters.forEach(function(s){var m=routerMaterials[s.idx];if(!m)return;var qty=Number(s.qty)||0;if(qty>0)items.push({description:m.description,qty:qty,amount:Number(s.amount)||0,supplier:String(s.supplier||'')})});var btn=$('costSaveBtn');btn.disabled=true;var oldText=btn.textContent;btn.textContent='Saving…';try{await api('/api/costs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({date:$('costDate').value||today(),orderNumber:orderNumber,items:items})});toast('Cost entry saved to Google Sheets.');clearCostForm();await loadCosts()}catch(err){toast(err.setup?'Write access needs Railway credentials.':err.message,true)}finally{btn.disabled=false;btn.textContent=oldText}}
  function renderCostLog(){var tbody=$('costLogRows');var grouped={};costEntries.forEach(function(e){(grouped[e.orderNumber]=grouped[e.orderNumber]||[]).push(e)});var orderKeys=Object.keys(grouped).sort();var html='';var totalEntries=0;orderKeys.forEach(function(order){var lines=grouped[order];var subtotal=lines.reduce(function(s,l){return s+(Number(l.total)||0)},0);var date=lines[0]&&lines[0].date||'';html+='<tr class="order-header"><td colspan="8" data-label="Order">Order '+esc(order)+' · '+esc(date)+' · '+money(subtotal)+' total</td></tr>';lines.forEach(function(l){totalEntries++;html+='<tr data-cost-id="'+esc(l.id)+'"><td data-label="Date">'+esc(l.date)+'</td><td data-label="Order #" class="order-cell">'+esc(l.orderNumber)+'</td><td data-label="Description">'+esc(l.description)+'</td><td data-label="Supplier">'+esc(l.supplier||'—')+'</td><td data-label="QTY">'+(Number(l.qty)||0)+'</td><td data-label="Amount">'+money(l.amount)+'</td><td data-label="Total">'+money(l.total)+'</td><td data-label="Actions"><div class="row-actions"><button class="icon-btn cost-edit" aria-label="Edit line" title="Edit">✎</button><button class="icon-btn delete cost-del" aria-label="Delete line" title="Delete">×</button></div></td></tr>'})});tbody.innerHTML=html;$('costEmpty').className='empty'+(totalEntries?'':' show');$('costCount').textContent=totalEntries+' entr'+(totalEntries===1?'y':'ies');tbody.querySelectorAll('.cost-edit').forEach(function(b){b.onclick=function(){openCostEdit(b.closest('tr').dataset.costId)}});tbody.querySelectorAll('.cost-del').forEach(function(b){b.onclick=function(){deleteCostLine(b.closest('tr').dataset.costId)}})}
  var costEditingId='';
