  $('costEditForm').onsubmit=saveCostEdit;$('costEditCancelBtn').onclick=closeCostEdit;$('costEditCloseBtn').onclick=closeCostEdit;$('costEditModal').onclick=function(e){if(e.target===$('costEditModal'))closeCostEdit()};document.addEventListener('keydown',function(e){if(e.key==='Escape'&&$('costEditModal').className.indexOf('show')>-1)closeCostEdit()});['costEditQty','costEditAmount'].forEach(function(id){$(id).addEventListener('input',computeCostEditTotal)});
  function deductionsFor(r){return (Number(r.commissionExpense)||0)+(Number(r.advertisingExpense)||0)+(Number(r.freightOutExpense)||0)+(Number(r.withHoldingTax)||0)+(Number(r.paymentFee)||0)+(Number(r.orderProcessingFee)||0)}
  function buildIncomeData(){var costByOrder={};costEntries.forEach(function(e){if(!e.orderNumber)return;costByOrder[e.orderNumber]=(costByOrder[e.orderNumber]||0)+(Number(e.total)||0)});return records.filter(hasIncome).map(function(r){var price=Number(r.price)||0;var cost=costByOrder[r.orderNumber]||0;var deductions=deductionsFor(r);var income=price-cost-deductions;var gp=price>0?(income/price)*100:0;return {r:r,price:price,cost:cost,deductions:deductions,income:income,gp:gp}})}
  function filterIncomeData(all){var q=($('idSearch').value||'').toLowerCase().trim();var product=$('idProductFilter').value||'';var date=$('idDateFilter').value||'';var source=$('idSourceFilter').value||'';return all.filter(function(d){var r=d.r;var blob=[r.customerName,r.orderNumber,r.description,r.address,r.source,r.date].join(' ').toLowerCase();if(q&&blob.indexOf(q)<0)return false;if(product&&r.description!==product)return false;if(!matchesDate(r,date))return false;if(source&&r.source!==source)return false;return true})}
  function renderIncomeDetails(){var all=buildIncomeData();var data=filterIncomeData(all);var totalRev=data.reduce(function(s,d){return s+d.price},0);var totalCost=data.reduce(function(s,d){return s+d.cost},0);var totalDeduct=data.reduce(function(s,d){return s+d.deductions},0);var totalNet=data.reduce(function(s,d){return s+d.income},0);var avgGP=totalRev>0?(totalNet/totalRev)*100:0;$('idRevenue').textContent=money(totalRev);$('idCost').textContent=money(totalCost);$('idDeductions').textContent=money(totalDeduct);$('idIncome').textContent=money(totalNet);$('idGP').textContent=avgGP.toFixed(1)+'%';$('idDonutValue').textContent=avgGP.toFixed(0)+'%';var tbody=$('incomeDetailRows');tbody.innerHTML=data.map(function(d){var gpClass=d.gp>=30?'high':d.gp>=10?'mid':'low';var incClass=d.income<0?'id-income neg':'id-income';return '<tr><td data-label="Date">'+esc(d.r.date)+'</td><td data-label="Customer" class="id-customer">'+esc(d.r.customerName||'—')+'</td><td data-label="Address">'+esc(d.r.address||'—')+'</td><td data-label="Order No."><span class="order-tag">'+esc(d.r.orderNumber||'—')+'</span></td><td data-label="Source">'+esc(d.r.source||'—')+'</td><td data-label="Product">'+esc(d.r.description||'—')+'</td><td data-label="Price" class="id-money">'+money(d.price)+'</td><td data-label="Cost & Expenses" class="id-cost">'+money(d.cost)+'</td><td data-label="Deductions" class="id-deduct">'+money(d.deductions)+'</td><td data-label="Income" class="'+incClass+'">'+money(d.income)+'</td><td data-label="GP %"><span class="gp-badge '+gpClass+'">'+d.gp.toFixed(1)+'%</span></td></tr>'}).join('');$('incomeDetailsEmpty').className='empty'+(data.length?'':' show');$('incomeDetailsCount').textContent=data.length+' order'+(data.length===1?'':'s');drawIncomeTrend(data);drawIncomeDonut(totalRev,totalCost,totalDeduct,totalNet)}
  function drawIncomeTrend(data){var el=$('incomeTrendChart');if(!el)return;var p=prepareCanvas('incomeTrendChart'),x=p.x,w=p.w,h=p.h;var months=[],vals=[],now=new Date();for(var i=5;i>=0;i--){var d=new Date(now.getFullYear(),now.getMonth()-i,1);months.push(d.toLocaleString('en',{month:'short'}));vals.push(data.filter(function(dd){var rd=new Date((dd.r.date||'')+'T00:00:00');return rd.getMonth()===d.getMonth()&&rd.getFullYear()===d.getFullYear()}).reduce(function(s,dd){return s+dd.income},0))}var maxV=Math.max.apply(null,vals.concat([1]).map(Math.abs)),pad=18,gap=11,bw=(w-pad*2-gap*5)/6;x.clearRect(0,0,w,h);for(var j=0;j<6;j++){var v=vals[j],bh=Math.max(3,(Math.abs(v)/maxV)*(h-35)),left=pad+j*(bw+gap),top=h-22-bh;var g=x.createLinearGradient(0,top,0,h);if(v>=0){g.addColorStop(0,'#6ee7b7');g.addColorStop(1,'#065f46')}else{g.addColorStop(0,'#fca5a5');g.addColorStop(1,'#991b1b')}x.fillStyle=g;x.beginPath();if(x.roundRect)x.roundRect(left,top,bw,bh,[5,5,1,1]);else x.rect(left,top,bw,bh);x.fill();x.fillStyle='#64748b';x.font='10px system-ui';x.textAlign='center';x.fillText(months[j],left+bw/2,h-5)}}
  function drawIncomeDonut(totalRev,totalCost,totalDeduct,totalNet){var el=$('incomeDonutChart');if(!el)return;var p=prepareCanvas('incomeDonutChart'),x=p.x,w=p.w,h=p.h;var pos=Math.max(totalNet,0);var sum=totalCost+totalDeduct+pos;var cx=w/2,cy=h/2,r=Math.min(w,h)*.34,start=-Math.PI/2;x.clearRect(0,0,w,h);x.lineWidth=14;if(!sum){x.strokeStyle='#e2e8f0';x.beginPath();x.arc(cx,cy,r,0,Math.PI*2);x.stroke();return}var parts=[{v:totalCost,c:'#f59e0b'},{v:totalDeduct,c:'#ef4444'},{v:pos,c:'#10b981'}];parts.forEach(function(part){if(!part.v)return;var end=start+Math.PI*2*(part.v/sum);x.strokeStyle=part.c;x.beginPath();x.arc(cx,cy,r,start+.025,end-.025);x.stroke();start=end})}
  function renderRawMatEditRows(){var tbody=$('rmRows');if(!rawMaterials.length){tbody.innerHTML='<tr><td colspan="7" class="status-msg">RawMaterials sheet is empty or unavailable.</td></tr>';$('rmCount').textContent='0 materials';return}$('rmCount').textContent=rawMaterials.length+' material'+(rawMaterials.length===1?'':'s');tbody.innerHTML=rawMaterials.map(function(m,i){var sups=Array.isArray(m.suppliers)?m.suppliers:[];var chips=sups.length?sups.map(function(s){return '<span class="supplier-chip">'+esc(s)+'</span>'}).join(''):'<span class="rm-empty-sups">No suppliers yet</span>';var full=sups.length>=10;return '<tr data-row="'+m.rowIndex+'" data-idx="'+i+'"><td class="rm-num" data-mob-label="#">'+(i+1)+'</td><td data-mob-label="Description"><input class="rm-desc" type="text" value="'+esc(m.description)+'" aria-label="Description"></td><td class="rm-qty" data-mob-label="QTY">×'+(Number(m.qty)||0)+'</td><td data-mob-label="Unit Price"><input class="rm-price" type="number" step="0.01" min="0" inputmode="decimal" value="'+(Number(m.unitPrice)||0).toFixed(2)+'" aria-label="Unit price"></td><td class="rm-amount" data-mob-label="Amount">'+money(m.amount)+'</td><td class="rm-sup-cell" data-mob-label="Suppliers"><div class="supplier-chips">'+chips+'</div><div class="supplier-add-row"><input class="rm-new-sup" type="text" placeholder="Add new supplier" '+(full?'disabled':'')+' aria-label="New supplier"><button type="button" class="btn btn-sm rm-add-sup" '+(full?'disabled':'')+'>＋ Add</button></div>'+(full?'<div class="rm-slot-note">All 10 supplier slots are full.</div>':'')+'</td><td data-mob-label=""><button type="button" class="btn primary btn-sm rm-save">Save row</button></td></tr>'}).join('');tbody.querySelectorAll('.rm-save').forEach(function(btn){btn.onclick=function(){saveRawMatRow(btn.closest('tr'))}});tbody.querySelectorAll('.rm-add-sup').forEach(function(btn){btn.onclick=function(){addRawMatSupplier(btn.closest('tr'))}});tbody.querySelectorAll('.rm-new-sup').forEach(function(inp){inp.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();addRawMatSupplier(inp.closest('tr'))}})})}
  async function saveRawMatRow(tr){var rowIndex=Number(tr.dataset.row);var desc=tr.querySelector('.rm-desc').value.trim();var price=Number(tr.querySelector('.rm-price').value)||0;if(!desc){toast('Description cannot be empty.',true);return}var btn=tr.querySelector('.rm-save');btn.disabled=true;var oldText=btn.textContent;btn.textContent='Saving…';try{await api('/api/raw-materials/'+rowIndex,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({description:desc,unitPrice:price})});toast('Row saved.');await loadRawMaterials();renderRawMatEditRows()}catch(err){toast(err.setup?'Write access needs Railway credentials.':err.message,true);btn.disabled=false;btn.textContent=oldText}}
